INSERT INTO `notice` VALUES (13,'RECOMMEND',32,'서비스 기능 업데이트 안내 (2026.03)','안녕하세요.\n더 나은 서비스 제공을 위해 일부 기능이 업데이트되었습니다.\n\n주요 변경 사항\n* 마이페이지 UI 개선\n* 알림 기능 안정화\n* 일부 버그 수정\n\n앞으로도 더 편리한 서비스를 제공하기 위해 노력하겠습니다.\n감사합니다.',0,0,0,'2026-03-10 12:27:33','2026-03-10 12:28:36'),(14,'RECOMMEND',32,'시스템 점검 안내 (3월 15일 02:00 ~ 04:00)','안정적인 서비스 제공을 위해 아래 시간 동안 시스템 점검이 진행됩니다.\n\n점검 일정\n* 2026년 3월 15일 02:00 ~ 04:00\n\n점검 시간 동안 서비스 이용이 일시적으로 제한될 수 있습니다.\n이용에 불편을 드려 죄송합니다.',0,0,0,'2026-03-10 12:28:08',NULL),(15,'RECOMMEND',32,'개인정보 처리방침 변경 안내','개인정보 보호 정책이 일부 변경되어 안내드립니다.\n\n변경 사항\n* 개인정보 보관 기간 명확화\n* 서비스 이용 로그 관리 정책 추가\n\n변경된 내용은 2026년 4월 1일부터 적용됩니다.',0,0,0,'2026-03-10 12:28:25','2026-03-10 12:28:48'),(16,'RECOMMEND',32,'알림 기능이 새롭게 추가되었습니다','사용자 편의를 위해 새로운 알림 기능이 추가되었습니다.\n\n이제 다음과 같은 알림을 받아볼 수 있습니다.\n* 중요 공지사항 안내\n* 서비스 업데이트 알림\n* 계정 관련 알림\n\n마이페이지에서 알림 설정을 변경할 수 있습니다.',0,0,0,'2026-03-10 12:29:21',NULL),(17,'RECOMMEND',32,'회원 감사 이벤트 안내','서비스를 이용해주시는 회원 여러분께 감사드립니다.\n\n감사의 의미로 작은 이벤트를 준비했습니다.\n\n이벤트 기간\n* 2026년 3월 10일 ~ 3월 31일\n\n자세한 내용은 이벤트 페이지를 확인해 주세요.',0,0,0,'2026-03-10 12:29:40',NULL),(48,'RECOMMEND',32,'서비스 업데이트 안내','더 나은 서비스 제공을 위해 일부 기능이 업데이트되었습니다.',0,0,0,'2026-03-10 12:33:10',NULL),(49,'RECOMMEND',32,'커뮤니티 이용 정책 안내','건전한 커뮤니티 환경을 위해 이용 정책을 안내드립니다.',0,0,0,'2026-03-10 12:33:10',NULL),(50,'RECOMMEND',32,'시스템 점검 안내','안정적인 서비스 제공을 위해 시스템 점검이 진행됩니다.',0,0,0,'2026-03-10 12:33:10',NULL),(51,'RECOMMEND',32,'추천 게시판 이용 방법','추천 게시판 이용 방법을 안내드립니다.',0,0,0,'2026-03-10 12:33:10',NULL),(52,'RECOMMEND',32,'공지사항 이용 안내','공지사항 게시판 이용 방법을 안내드립니다.',0,0,0,'2026-03-10 12:33:10',NULL),(53,'RECOMMEND',32,'추천 게시글 작성 가이드','추천 게시글 작성 시 참고해주세요.',0,0,0,'2026-03-10 12:33:10',NULL),(54,'RECOMMEND',32,'신규 기능 업데이트','신규 기능이 추가되어 안내드립니다.',0,0,0,'2026-03-10 12:33:10',NULL),(55,'RECOMMEND',32,'콘텐츠 추천 이벤트 안내','콘텐츠 추천 이벤트가 진행됩니다.',0,0,0,'2026-03-10 12:33:10',NULL),(56,'RECOMMEND',32,'서비스 안정화 작업 안내','서비스 안정화를 위한 작업이 예정되어 있습니다.',0,0,0,'2026-03-10 12:33:10',NULL),(57,'RECOMMEND',32,'추천 게시판 규칙 안내','추천 게시판 이용 규칙을 확인해주세요.',0,0,0,'2026-03-10 12:33:10',NULL),(58,'RECOMMEND',32,'공지사항 등록 테스트','공지사항 테스트 데이터입니다.',0,0,0,'2026-03-10 12:33:10',NULL),(59,'RECOMMEND',32,'추천 게시판 테스트','추천 게시판 테스트 공지입니다.',0,0,0,'2026-03-10 12:33:10',NULL),(60,'RECOMMEND',32,'서비스 이용 안내','서비스 이용 시 참고해주세요.',0,0,1,'2026-03-10 12:33:10',NULL),(61,'RECOMMEND',32,'콘텐츠 추천 팁','좋은 콘텐츠를 추천하는 방법을 안내합니다.',0,0,0,'2026-03-10 12:33:10',NULL),(62,'RECOMMEND',32,'업데이트 예정 안내','다음 업데이트 예정 사항을 안내드립니다.',0,0,0,'2026-03-10 12:33:10',NULL),(63,'RECOMMEND',32,'추천 게시판 이벤트','추천 게시판 이벤트가 진행됩니다.',0,0,0,'2026-03-10 12:33:10',NULL),(64,'RECOMMEND',32,'공지사항 테스트 데이터2','공지사항 더미 데이터입니다.',0,0,0,'2026-03-10 12:33:10',NULL),(65,'RECOMMEND',32,'추천 게시판 테스트 데이터2','추천 게시판 더미 데이터입니다.',0,0,0,'2026-03-10 12:33:10',NULL),(66,'RECOMMEND',32,'서비스 개선 안내','서비스 품질 개선 작업이 진행됩니다.',0,0,0,'2026-03-10 12:33:10',NULL),(67,'RECOMMEND',32,'추천 게시판 이용 안내','추천 게시판 이용 방법을 다시 안내드립니다.',0,0,0,'2026-03-10 12:33:10',NULL),(68,'RECOMMEND',32,'공지사항 업데이트','공지사항이 업데이트되었습니다.',0,0,0,'2026-03-10 12:33:10',NULL),(69,'RECOMMEND',32,'추천 콘텐츠 안내','추천 콘텐츠를 소개합니다.',0,0,0,'2026-03-10 12:33:10',NULL),(70,'RECOMMEND',32,'서비스 점검 안내','서비스 점검이 예정되어 있습니다.',0,0,0,'2026-03-10 12:33:10',NULL),(71,'RECOMMEND',32,'추천 게시판 가이드','추천 게시판 이용 가이드입니다.',0,0,0,'2026-03-10 12:33:10',NULL),(72,'RECOMMEND',32,'공지사항 안내','공지사항 관련 안내입니다.',0,0,0,'2026-03-10 12:33:10',NULL),(73,'RECOMMEND',32,'추천 게시판 운영 정책','추천 게시판 운영 정책을 안내드립니다.',0,0,1,'2026-03-10 12:33:10',NULL),(74,'RECOMMEND',32,'서비스 개선 작업','서비스 개선 작업이 진행됩니다.',0,1,1,'2026-03-10 12:33:10',NULL),(75,'RECOMMEND',32,'추천 게시글 작성 규칙','추천 게시글 작성 규칙을 확인해주세요.',0,0,0,'2026-03-10 12:33:10',NULL),(76,'RECOMMEND',32,'공지사항 테스트 데이터3','공지사항 테스트용 데이터입니다.',0,0,0,'2026-03-10 12:33:10',NULL),(77,'RECOMMEND',32,'추천 게시판 테스트 데이터3','추천 게시판 테스트용 데이터입니다.',0,0,0,'2026-03-10 12:33:10',NULL);
